    display: flex;
    flex-direction: column;
    align-items: flex-start;
    max-width: 100%;
    padding: --spacing(4) --spacing(5);
    background-color: color-mix(in oklab, var(--color-ink) 62%, transparent);
    -webkit-backdrop-filter: blur(--spacing(2));
    backdrop-filter: blur(--spacing(2));
}


/* Light bottom scrim for depth; the panel behind the copy carries the contrast. */
.category-banner--has-image .category-banner__media::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    pointer-events: none;
    background: linear-gradient(
        to top,
        color-mix(in oklab, var(--color-ink) 40%, transparent) 0%,
        transparent 55%
    );
}

